-- Health History intake form (EN) as a published encounter template.
-- The Spanish twin was dropped: two copies of the same form drifted apart
-- and answers landed in whichever one the clinician happened to pick.
-- Source: "Health History Form 2026" (© 2007, 2023 Integrative Nutrition, LLC,
-- reprinted with permission). Patient demographics are omitted — they live on
-- the patient profile; forms are linked to the patient when filled.
-- Idempotent: skips any template whose name already exists for the org.
DO $$
DECLARE
  org uuid;
  tpl uuid;
BEGIN
  SELECT id INTO org FROM organizations ORDER BY created_at LIMIT 1;
  IF org IS NULL THEN RAISE EXCEPTION 'No organization found'; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM encounter_templates WHERE organization_id = org AND name = 'Health History (EN)'
  ) THEN
    INSERT INTO encounter_templates (organization_id, name)
    VALUES (org, 'Health History (EN)')
    RETURNING id INTO tpl;
    INSERT INTO encounter_template_versions (organization_id, template_id, version, schema, published_at)
    VALUES (org, tpl, 1, '[{"key":"h_goals","label":"Health and wellness goals","type":"heading"},{"key":"goals","label":"What are your health and wellness goals? Why are they important to you?","type":"textarea"},{"key":"h_health_info","label":"Health information","type":"heading"},{"key":"health_story","label":"What''s the most important thing you''d like to share about your health story?","type":"textarea"},{"key":"primary_care_provider","label":"Primary care provider","type":"text"},{"key":"other_specialists","label":"Other physicians or specialists","type":"textarea"},{"key":"other_practitioners","label":"Practitioners, therapists, healers, etc.","type":"textarea"},{"key":"supplements_medications","label":"Supplements or medications you take","type":"textarea"},{"key":"healthcare_barriers","label":"Barriers or challenges to accessing healthcare","type":"textarea"},{"key":"h_medical_info","label":"Medical information","type":"heading"},{"key":"medical_conditions","label":"Medical diagnoses or conditions","type":"textarea"},{"key":"serious_illness_history","label":"History of serious illnesses, hospitalizations, injuries, or surgeries","type":"textarea"},{"key":"h_family_history","label":"Family history","type":"heading"},{"key":"family_mother","label":"Health of your mother","type":"textarea"},{"key":"family_father","label":"Health of your father","type":"textarea"},{"key":"childhood_health","label":"Notable childhood health information","type":"textarea"},{"key":"other_family_history","label":"Other notable family or personal health information","type":"textarea"},{"key":"h_physical","label":"Physical health","type":"heading"},{"key":"current_weight","label":"Current weight","type":"text"},{"key":"height","label":"Height","type":"text"},{"key":"sleep_hours","label":"Hours of sleep per night (average)","type":"number","min":0,"max":24},{"key":"sleep_quality","label":"How would you describe your quality of sleep?","type":"textarea"},{"key":"energy_level","label":"Energy level most days (1 = very low, 5 = very high)","type":"scale","min":1,"max":5},{"key":"pain_stiffness","label":"Pain, stiffness, or swelling on a regular basis — please explain","type":"textarea"},{"key":"h_metabolic","label":"Metabolic health","type":"heading"},{"key":"metabolic_blood_sugar","label":"Blood sugar imbalances","type":"checkbox"},{"key":"metabolic_blood_pressure","label":"Elevated blood pressure","type":"checkbox"},{"key":"metabolic_cholesterol","label":"Elevated cholesterol","type":"checkbox"},{"key":"metabolic_triglycerides","label":"Elevated triglycerides","type":"checkbox"},{"key":"metabolic_other","label":"Other metabolic concerns","type":"text"},{"key":"h_digestive","label":"Digestive health","type":"heading"},{"key":"digestive_bloating","label":"Bloating","type":"checkbox"},{"key":"digestive_constipation","label":"Constipation","type":"checkbox"},{"key":"digestive_diarrhea","label":"Diarrhea","type":"checkbox"},{"key":"digestive_gas","label":"Gas","type":"checkbox"},{"key":"digestive_nausea","label":"Nausea","type":"checkbox"},{"key":"digestive_stomach_pain","label":"Stomach pain","type":"checkbox"},{"key":"digestive_other","label":"Other digestive concerns","type":"text"},{"key":"bowel_movements_per_day","label":"Bowel movements per day (average)","type":"number","min":0,"max":20},{"key":"h_reproductive","label":"Reproductive health","type":"heading"},{"key":"reproductive_infertility","label":"Infertility","type":"checkbox"},{"key":"reproductive_irregular_cycle","label":"Irregular menstrual cycle","type":"checkbox"},{"key":"reproductive_low_libido","label":"Low libido","type":"checkbox"},{"key":"reproductive_other","label":"Other reproductive concerns","type":"text"},{"key":"h_hormonal","label":"Hormonal health","type":"heading"},{"key":"hormonal_thyroid","label":"Thyroid condition","type":"checkbox"},{"key":"hormonal_toxin_exposure","label":"Toxin exposure","type":"checkbox"},{"key":"hormonal_symptoms","label":"Signs or symptoms of hormonal imbalance","type":"textarea"},{"key":"h_immune","label":"Immune health","type":"heading"},{"key":"immune_autoimmune","label":"Autoimmune conditions","type":"checkbox"},{"key":"immune_low_vitamin_d","label":"Low vitamin D level","type":"checkbox"},{"key":"immune_frequent_illness","label":"Frequent illness or infection","type":"checkbox"},{"key":"allergies_sensitivities","label":"Allergies and sensitivities","type":"textarea"},{"key":"immune_other","label":"Other immune concerns","type":"text"},{"key":"h_brain","label":"Brain health","type":"heading"},{"key":"brain_fog","label":"Brain fog","type":"checkbox"},{"key":"brain_concentration","label":"Difficulty concentrating","type":"checkbox"},{"key":"brain_forgetfulness","label":"Forgetfulness","type":"checkbox"},{"key":"brain_other","label":"Other brain health concerns","type":"text"},{"key":"h_oral","label":"Oral health","type":"heading"},{"key":"oral_cavities","label":"Cavities","type":"checkbox"},{"key":"oral_dry_mouth","label":"Dry mouth","type":"checkbox"},{"key":"oral_mouth_breathing","label":"Mouth breathing / snoring","type":"checkbox"},{"key":"oral_gum_bleeding","label":"Gum bleeding","type":"checkbox"},{"key":"oral_other","label":"Other oral health concerns","type":"text"},{"key":"h_nutrition","label":"Nutrition","type":"heading"},{"key":"foods_grew_up","label":"What foods did you grow up eating?","type":"textarea"},{"key":"past_food_relationship","label":"Past relationship or history with food; specific memories about food or eating","type":"textarea"},{"key":"current_food_relationship","label":"Current relationship with food","type":"textarea"},{"key":"food_allergies","label":"Food allergies or intolerances","type":"textarea"},{"key":"challenge_preparing_meals","label":"Challenges with preparing meals","type":"checkbox"},{"key":"challenge_food_access","label":"Challenges with access to food","type":"checkbox"},{"key":"challenge_chewing","label":"Difficulties chewing or swallowing","type":"checkbox"},{"key":"challenge_appetite","label":"Poor appetite","type":"checkbox"},{"key":"substance_alcohol","label":"Alcohol","type":"checkbox"},{"key":"substance_tobacco","label":"Tobacco products","type":"checkbox"},{"key":"substance_other","label":"Other substances","type":"text"},{"key":"eating_approach","label":"Specific eating approach or practice (e.g., vegan, ketogenic, kosher)","type":"textarea"},{"key":"meals_breakfast","label":"Typical breakfast","type":"textarea"},{"key":"meals_lunch","label":"Typical lunch","type":"textarea"},{"key":"meals_dinner","label":"Typical dinner","type":"textarea"},{"key":"meals_snacks","label":"Typical snacks","type":"textarea"},{"key":"water_daily","label":"How much water do you drink daily?","type":"text"},{"key":"nutrition_changes","label":"What would you like to change about your nutrition?","type":"textarea"},{"key":"h_mental","label":"Mental and emotional health","type":"heading"},{"key":"mental_overall","label":"How would you describe your overall mental and emotional health?","type":"textarea"},{"key":"mental_support","label":"How do you like to support your mental health?","type":"textarea"},{"key":"stress_coping","label":"How do you cope with stress?","type":"textarea"},{"key":"h_emotions","label":"How often do you experience… (1 = never, 5 = always)","type":"heading"},{"key":"emotion_anger","label":"Anger","type":"scale","min":1,"max":5},{"key":"emotion_excitement","label":"Excitement","type":"scale","min":1,"max":5},{"key":"emotion_fear","label":"Fear","type":"scale","min":1,"max":5},{"key":"emotion_joy","label":"Joy","type":"scale","min":1,"max":5},{"key":"emotion_love","label":"Love","type":"scale","min":1,"max":5},{"key":"emotion_sadness","label":"Sadness","type":"scale","min":1,"max":5},{"key":"emotion_stress","label":"Stress","type":"scale","min":1,"max":5},{"key":"emotion_worry","label":"Worry","type":"scale","min":1,"max":5},{"key":"h_spiritual","label":"Spiritual health","type":"heading"},{"key":"spirituality_role","label":"What role does spirituality play in your life, if any?","type":"textarea"},{"key":"h_lifestyle","label":"Lifestyle","type":"heading"},{"key":"important_relationships","label":"What are the important relationships in your life?","type":"textarea"},{"key":"social_life","label":"Anything you''d like to share about your social life?","type":"textarea"},{"key":"live_with","label":"Who do you live with, if anyone?","type":"text"},{"key":"work_hours_week","label":"Hours worked per week (typical)","type":"number","min":0,"max":120},{"key":"hobbies","label":"Hobbies or recreational activities you enjoy","type":"textarea"},{"key":"movement_role","label":"Role of movement (sports, exercise, physical activity) in your life","type":"textarea"},{"key":"h_additional","label":"Additional comments","type":"heading"},{"key":"additional_comments","label":"Is there anything else you''d like to share?","type":"textarea"}]'::jsonb, now());
  END IF;

END $$;
